    lyrics: {
      tamil: `|| ஸ்ரீ அபிராமி அந்தாதி ||
அருளியவர்: ஸ்ரீ அபிராமி பட்டர்
=== காப்பு ===
தாரமர் கொன்றையும் செண்பக மாலையுஞ் சாத்தும்தில்லை
ஊரர் தம் பாகத்து உமை மைந்தனே !  உலகேழும் பெற்ற
சீர் அபிராமி அந்தாதி எப்போதும் என் சிந்தையுள்ளே
காரமர் மேனிக் கணபதியே ! நிற்கக் கட்டுரையே
=== பாடல் 1 ===
உதிக்கின்ற செங்கதிர் உச்சித் திலகம், உணர்வுடையோர்
மதிக்கின்ற மாணிக்கம், மாதுளம்போது மலர்க்கமலை
துதிக்கின்ற மின்கொடி, மென்கடிக் குங்கும தோயம் என்ன
விதிக்கின்ற மேனி அபிராமி என்தன் விழுத்துணையே
=== பாடல் 2 ===
துணையும், தொழுந் தெய்வமும், பெற்ற தாயும், சுருதிகளின்
பணையும், கொழுந்தும், பதிகொண்ட வேரும், பனி மலர்பூங்
கணையும் கரும்புசிலையும், மென் பாசாங்குசமும், கையில்
அணையும் திரிபுர சுந்தரி ஆவது அறிந்தனமே
=== பாடல் 3 ===
அறிந்தேன் எவரும் அறியா மறையை அறிந்துகொண்டு
செறிந்து, உனது திருவடிக்கே, திருவே ! வெருவிப்
பிறிந்தேன், நின், அன்பர் பெருமை எண்ணாத கரும நெஞ்சால்
மறிந்தே விழுநரகுக்கு உறவாய மனிதரையே !
=== பாடல் 4 ===
மனிதரும் தேவரும், மாயா முனிவரும் வந்து சென்னிக்
குனிதரும், சேவடிக்கோமளமே !  கொன்றை வார்சடைமேல்
பனிதரும், திங்களும் பாம்பும், பகீரதியும் படைத்த
புனிதரும் நீயுமென்புந்தி எந்நாளும், பொருந்துகவே.
=== பாடல் 5 ===
பொருந்திய முப்புரை, செப்புரை செய்யும் புணர்முலையாள்
வருந்திய வஞ்சி மருங்குல் மனோன்மணி !  வார்சடையோன்
அருந்திய நஞ்சு அமுதாக்கிய அம்பிகை அம்புயம் மேல்
திருந்திய சுந்தரி, அந்தரி, பாதம் என் சென்னியதே.
=== பாடல் 6 ===
சென்னியது உன் பொற் திருவடித் தாமரை சிந்தையுள்ளே
மன்னியது உன்திரு மந்திரம் சிந்துர வண்ணப் பெண்ணே
முன்னிய நின் அடியாருடன் கூடி, முறை முறையே
பன்னியது, என்றும் உன்தன் பரமாகம பத்ததியே.
=== பாடல் 7 ===
ததியுறு மத்திற் சுழலும் என் ஆவி, தளர்வவலதோர்
கதியுரு வண்ணம் கருது கண்டாய் கமலாலயனும்
மதியுறு வேணி மகிழ்நனும், மாலும், வணங்கி என்றும்
துதியுறு சேவடியாய் சிந்துரானன சுந்தரியே!
=== பாடல் 8 ===
சுந்தரி, எந்தை துணைவி, என் பாசத் தொடரையெல்லாம்
வந்தரி, சிந்துர வண்ணத்தினாள், மகிடன் தலைமேல்
அந்தரி,நீலி, அழியாத கன்னிகை, ஆரணத்தோன்
கந்தரி கைதளத்தாள் மலர்த்தாள் என் கருத்தனவே.
=== பாடல் 9 ===
கருத்தன, எந்தைதன் கண்ணன வண்ணக் கனகவெற்பில்
பெருத்தன, பால் அழும் பிள்ளைக்கு நல்கின, பேர் அருள்கூர்
திருத்தன பாரமும்; ஆரமும் செங்கைச் சிலையும், அம்பும்
முருத்தன மூரலும், நீயும் அம்மே ! வந்து என் முன் நிற்கவே
=== பாடல் 10 ===
நின்றும் இருந்தும் கிடந்தும் நடந்தும் நினைப்பதுன்னை,
என்றும் வணங்குவது உன் மலர்த்தாள் ! எழுதாமறையின்
ஒன்றும் அரும் பொருளே ! அருளே !  உமையே !  இமயத்து
அன்றும் பிறந்தவளே !  அழியா முத்தி ஆனந்தமே !
=== பாடல் 11 ===
ஆனந்தமாய், என் அறிவாய் நிறைந்த அமுதமுமாய்,
வான் அந்தமான வடிவுடையாள், மறை நான்கினுக்கும்
தானந்தமான சரணார விந்தம் தவளநிறக்
கானந் தம் ஆடரங்காம் எம்பிரான் முடிக் கண்ணியதே.
=== பாடல் 12 ===
கண்ணியது உன் புகழ்; கற்பது உன் நாமம்; கசிந்துபத்தி
பண்ணியது உன் இரு பாதாம் புயத்தில்; பகல் இரவா
நண்ணியது உன்னை நயந்தோர் அவையத்து; நான் முன்செய்த
புண்ணியம் ஏது? என் அம்மே ! புவி ஏழையும் பூத்தவளே !
=== பாடல் 13 ===
பூத்தவளே !  புவனம் பதினான் கையும் பூத்த வண்ணம்
காத்தவளே ! பின் கரந்தவளே ! கறைக் கண்டனுக்கு
மூத்தவளே ! என்றும் மூவா முகுந்தற்கு இளையவளே !
மாத்தவளே !  உன்னை அன்றி, மற்றோர் தெய்வம் வந்திப்பதே
=== பாடல் 14 ===
வந்திப்பவர் உன்னை, வானவர் தானவர் ஆனவர்கள்;
சிந்திப்பவர், நற்றிசைமுகர் நாரணர் சிந்தையுள்ளே
பந்திப்பவர், அழியாப் பர மானந்தர்; பாரில் உன்னைச்
சந்திப்பதற்கு எளிதாம் எம்பிராட்டி நின் தண்ணளியே !
=== பாடல் 15 ===
தண்ணளிக்கு என்று முன்னே பல கோடி தவங்கள் செய்வார்,
மண்ணளிக்கும் செல்வமோ பெறுவார்? மதி வானவர்தம்
விண்ணளிக்கும் செல்வமும், அழியா முத்தி வீடும் அன்றோ?
பண்ணளிக்கும் சொற் பரிமள யாமளைப் பைங்கிளியே !
=== பாடல் 16 ===
கிளியே! கிளைஞர் மனத்தே கிடந்து கிளர்ந்து ஒளிரும்
ஒளியே! ஒளிரும் ஒளிக்கு இடமே! எண்ணில் ஒன்றும் இல்லா
வெளியே! வெளிமுதற் பூதங்களாகி விரிந்த அம்மே!
அளியேன் அறிவு அளவிற்கு அளவானது அதிசயமே!
=== பாடல் 17 ===
அதிசயமான வடிவுடையாள் ! அரவிந்தமெல்லாம்
துதிசய ஆனன சுந்தரவல்லி ! துணை இரதி
பதிசய மானது அபசய மாக முன் பார்த்தவர் தம்
மதிசய  மாக வன்றோ வாம பாகத்தை வவ்வியதே.
=== பாடல் 18 ===
வவ்விய பாகத்து இறைவரும் நீயும் மகிழ்ந்திருக்கும்
செவ்வியும், உங்கள் திருமணக் கோலமும், சிந்தையுள்ளே
அவ்வியம் தீர்த்து என்னை ஆண்ட பொற்பாதமும் ஆகிவந்து
வெவ்வியகாலன் என் மேல்வரும் போது, வெளிநிற்கவே
=== பாடல் 19 ===
வெளிநின்ற நின் திருமேனியைப் பார்த்து என் விழியும் நெஞ்சும்
களிநின்ற வெள்ளம் கரை கண்டதில்லை; கருத்தினுள்ளே
தெளிகின்ற ஞானம், திகழ்கின்றது என்ன திருவுளமோ?
ஒளிநின்ற கோணங்கள் ஒன்பதும் மேவி உறைபவளே !
=== பாடல் 20 ===
உறைகின்ற நின்திருக் கோயில் நின் கேள்வர் ஒரு பக்கமோ
அறைகின்ற நான்மறையின் அடியோ முடியோ அமுதம்
நிறைகின்ற வெண்திங்களோ கஞ்சமோ என்தன் நெஞ்சகமோ
மறைகின்ற வாரிதியோ பூரணாசல மங்கலையே
=== பாடல் 21 ===
மங்கலை, செங்கலை, சம்முலை யாள், மலையாள் ,வருணச்
சங்கலை செங்கைச் சகலகலாமயில் தாவு கங்கை
பொங்கலை தங்கும் புரிசடையோன் புடையாள், உடையாள்
பிங்கலை, நீலி, செய்யாள், வெளியாள் பசும்பெண் கொடியே !
=== பாடல் 22 ===
கொடியே! இளவஞ்சிக்கொம்பே - எனக்கு வம்பே
பழுத்த படியே ! மறையின் பரிமளமே ! பனி மால் இமயப்
பிடியே ! பிரமன் முதலாய தேவரைப் பெற்ற அம்மே !
அடியேன் இறந்து இங்கு இனிப்பிறவாமல் வந்து ஆண்டு கொள்ளே
=== பாடல் 23 ===
கொள்ளேன் மனத்தில் நின்கோலம் அல்லாதன்பர் கூட்டம் தன்னை
விள்ளேன்; பரசமயம் விரும்பேன் வியன் மூவுலகுக்கு
உள்ளே அனைத்தினுக்கும் புறம்பே உள்ளத்தேவிளைந்த
கள்ளே ! களிக்கும் கிளியே ! அளிய என்கண்மணியே!
=== பாடல் 24 ===
மணியே ! மணியின் ஒளியே ஒளிரும் மணிபுனைந்த
அணியே ! அணியும் அணிக்கழகே அணுகாதவர்க்குப்
பிணியே ! பிணிக்கு மருந்தே ! அமரர் பெருவிருந்தே !
பணியேன் ஒருவரை நின்பத்ம பாதம் பணிந்தபின்னே !
=== பாடல் 25 ===
பின்னே திரிந்து உன் அடியாரைப்பேணிப் பிறப்பறுக்க
முன்னே தவங்கள் முயன்றுகொண்டேன், முதல் மூவருக்கும்
அன்னே ! உலகுக்கு அபிராமி என்னும், அருமருந்தே!
என்னே இனி உன்னையான், மறவாமல் நின்று ஏத்துவனே!
=== பாடல் 26 ===
ஏத்தும் அடியவர் ஈரேழு உலகினையும் படைத்தும்
காத்தும் அழித்தும் திரிபவராம்; கமழ் பூங்கடம்பு
சாத்தும் குழல் அணங்கே, மணம் நாறும், நின்தாளிணைக்கென்
நாத்தங்கு புன்மொழி ஏறிய வாறு நகையுடைத்தே
=== பாடல் 27 ===
உடைத்தனை வஞ்சப் பிறவியை; உள்ளம் உருகும் அன்பு
படைத்தனை; பத்ம பதயுகம் சூடும் பணி எனக்கே
அடைத்தனை; நெஞ்சத்து அழுக்கை எல்லாம் நின் அருட்புனலால்
துடைத்தனை; சுந்தரி !  நின் அருள் ஏதென்று சொல்லுவதே
=== பாடல் 28 ===
சொல்லும் பொருளும் என ,நடமாடும் துணைவருடன்
புல்லும் பரிமளப் பூங்கொடியே ! நின் புதுமலர்த் தாள்
அல்லும் பகலும் தொழும் அவர்க்கே, அழியா அரசும்
செல்லும் தவநெறியும் சிவலோகமும் சித்திக்குமே.
=== பாடல் 29 ===
சித்தியும் சித்தி தரும் தெய்வம் ஆகித் திகழும்பரா
சத்தியும் சக்தி தழைக்கும் சிவமும் தவம்முயல்வார்
முத்தியும் முத்திக்கு வித்தும் வித்தாகி முளைத்தெழுந்த
புத்தியும் புத்தியின் உள்ளே புரக்கும் புரத்தை அன்றே.
=== பாடல் 30 ===
அன்றேதடுத்தென்னை ஆண்டுகொண்டாய்; கொண்டதல்ல என்கை
நன்றே உனக்கினி நான் என் செயினும் நடுக்கடலுள்
சென்றே வீழினும் கரையேற்றுகை நின் திருவுளமே
ஒன்றே! பல உருவே ! அருவே ! என் உமையவளே.
=== பாடல் 31 ===
உமையும் உமையொரு பாகரும் ஏக உருவில்வந்திங்கு
எமையும் தமக்கன்பு செய்யவைத்தார்;  இனி எண்ணுதற்குச்
சமயங்களும் இல்லை; ஈன்றெடுப்பாள் ஒரு தாயும் இல்லை;
அமையும், அமையுறு தோளியர் மேல்வைத்த ஆசையுமே !
=== பாடல் 32 ===
ஆசைக் கடலில் அகப்பட்டு ,அருள் அற்ற அந்தகன்கைப்
பாசத்தில் அல்லற்பட இருந்தேனை, நின் பாதம் எனும்
வாசக் கமலம் தலைமேல் வலியவைத்து ஆண்டு கொண்ட
நேசத்தைஎன் சொல்லுவேன் ? ஈசர்பாகத்து நேரிழையே !
=== பாடல் 33 ===
இழைக்கும் வினைவழியே அடும் காலன் எனை நடுங்க,
அழைக்கும்பொழுது வந்து அஞ்சல் என்பாய் அத்தர் சித்தம் எல்லாம்
குழைக்கும் களபக் குவிமுலை யாமளைக் கோமளமே !
உழைக்கும் பொழுது, உன்னையே அன்னையே என்பன் ஓடிவந்தே.
=== பாடல் 34 ===
வந்தே சரணம் புகும் அடியாருக்கு வானுலகம்
தந்தே பரிவொடு தான் போய் இருக்கும் சதுர்முகமும்,
பைந்தேன் அலங்கற் பருமணி ஆகமும், பாகமும் பொற்
செந்தேன் மலரும், அலர்கதிர் ஞாயிறும், திங்களுமே,
=== பாடல் 35 ===
திங்கட் பகவின் மணம் நாறும் சீறடி சென்னிவைக்க
எங்கட்  கொருதவம் எய்தியவா ! எண் இறந்தவிண்ணோர்
தங்கட்கும் இந்தத் தவம்எய்து மோதரங் கக்கடலுள்
வெங்கட்பணி அணை மேல்துயில் கூரும் விழுப்பொருளே !
=== பாடல் 36 ===
பொருளே ! பொருள் முடிக்கும் போகமே அரும் போகம் செய்யும்
மருளே !  மருளில் வரும்தெருளே ! என் மனத்து வஞ்சத்து
இருள் ஏதும் இன்றி ஒளிவெளி ஆகியிருக்கும் உன்றன்
அருள் ஏதறிகின்றிலேன் அம்புயாதனத் தம்பிகையே !
=== பாடல் 37 ===
கைக்கே அணிவது கன்னலும் பூவும்; கமலம் அன்ன
மெய்க்கே அணிவது வெண்முத்து மாலை; விட அரவின்
பைக்கே அணிவது பன்மணிக் கோவையும் பட்டும் எட்டுத்
திக்கே அணியும் திருவுடையானிடம் சேர்பவளே !
=== பாடல் 38 ===
பவளக் கொடியில் பழுத்த செவ்வாயும் பனிமுறுவல்
தவளத் திருநகையும் துணையாய் எங்கள் சங்கரனைத்
துவளப் பொருது துடியிடை சாய்க்கும் துணை முலையாள்
அவளைப் பணிமின் கண்டீர் அமராவதி ஆளுகைக்கே.
=== பாடல் 39 ===
ஆளுகைக்கு உன்தன் அடித்தாமரைகள் உண்டு ; அந்தகன்பால்
மீளுகைக்கு உன்தன் விழியின் கடை உண்டு ; மேல் இவற்றின்
மூளூகைக் கென் குறை, நின்குறையே அன்று ;  முப்புரங்கள்
மாளுகைக்கு அம்பு தொடுத்த வில்லான் பங்கில் வாணுதலே !
=== பாடல் 40 ===
வாணுதற் கண்ணியை விண்ணவர் யாவரும் வந்திறைஞ்சிப்
பேணுதற் கெண்ணிய எம்பெருமாட்டியை பேதைநெஞ்சில்
காணுதற் கண்ணியள் அல்லாத கன்னியைக் காணும் அன்பு
பூணுதற்கெண்ணிய எண்ணமன்றோ முன்செய் புண்ணியமே.
=== பாடல் 41 ===
புண்ணியம் செய்தனமே மனமே !  புதுப் பூங்குவளைக்
கண்ணியும் செய்ய கணவரும் கூடி, நம் காரணத்தால்
நண்ணி இங்கே வந்து தம் அடியார்கள் நடு இருக்கப்
பண்ணி, நம் சென்னியின்மேல் பத்மபாதம் பதித்திடவே
=== பாடல் 42 ===
இடங்கொண்டு விம்மி இணைகொண்டு இறுகி இளகிமுத்து
வடங்கொண்ட கொங்கைமலை கொண்டிறைவர் வலியநெஞ்சை
நடங்கொண்ட கொள்கை நலங்கொண்ட நாயகி ! நல்லரவின்
படங்கொண்ட அல்குல் பனி மொழி, வேதப் பரிபுரையே
=== பாடல் 43 ===
பரிபுரச் சீரடிப் பாசாம்குசை,பஞ்சபாணி இன்சொல்
திரிபுர சுந்தரி ! சிந்துர மேனியள் ! தீமை நெஞ்சில்
புரிபுர வஞ்சரை அஞ்சக்குனி பொருப் புச்சிலைக்கை,
எரிபுரை மேனி, இறைவர் செம் பாகத் திருந்தவளே !
=== பாடல் 44 ===
தவளே இவள் எங்கள் சங்கரனார் மனைமங்கலமாம்
அவளே, அவர்தமக் கன்னையும் ஆயினள்; ஆகையினால்
இவளே கடவுளர் யாவர்க்கும் மேலை இறைவியுமாம்;
துவளேன்,இனியொரு தெய்வம் உண்டாக மெய்த்தொண்டு செய்தே.
=== பாடல் 45 ===
தொண்டு செய்யாது, நின்பாதம் தொழாது, துணிந்திச்சையே
பண்டு செய்தார் உளரோ இலரோ ? அப்பரி சடியேன்
கண்டு செய்தால் ,அது கைதவமோ அன்றிச் செய்தவமோ ?
மிண்டு செய்தாலும் பொறுக்கை நன்றே பின்வெறுக்கை அன்றே.
=== பாடல் 46 ===
வெறுக்கும் தகைமைகள் செய்யினும் தம் அடியாரைமிக்கோர்
பொறுக்கும் தகைமை புதியது அன்றே ;புது நஞ்சை உண்டு
கறுக்கும் திருமிடற்றான் இடப்பாகம் கலந்த பொன்னே !
மறுக்கும் தகைமைகள் செய்யினும், யான் உன்னை வாழ்த்துவனே.
=== பாடல் 47 ===
வாழும்படி ஒன்று கண்டு கொண்டேன் மனத்தே ஒருவர்
வீழும்படி அன்று; விள்ளும் படி அன்று; வேலை நிலம்
ஏழும் ,பருவரை எட்டும், எட்டாமல் இரவு பகல்
சூழும் சுடர்க்கு நடுவே கிடந்து சுடர்கின்றதே.
=== பாடல் 48 ===
சுடரும் கலைமதி துன்றும் சடைமுடிக் குன்றில் ஒன்றிப்
படரும் பரிமளப் பச்சைக் கொடியைப் பதித்து, நெஞ்சில்
இடரும் தவிர்த்து இமைபோதிருப்பார், பின்னும் எய்துவரோ
குடரும் கொழுவும் குருதியும் தோயும் குரம்பையிலே
=== பாடல் 49 ===
குரம்பை அடித்துக் குடி புக்க ஆவி, வெங் கூற்றுக்கு இட்ட
வரம்பை அடுத்து மறுகும் அப்போது, வளைக்கை அமைத்து
அரம்பையடுத்த அரிவையர் சூழவந்து, அஞ்சல் ,என்பாய்
நரம்பை அடுத்து இசைவடி வாய்நின்ற நாயகியே
=== பாடல் 50 ===
நாயகி நான்முகி, நாராயணிகை நளின பஞ்ச
சாயகி சாம்பவி, சங்கரி ,சாமளை சாதி நச்சு
வாயகி, மாலினி, வாராகி சூலினி, மாதங்கி என்று
ஆயகியாதி உடையாள் சரணம் அரண் நமக்கே.
=== பாடல் 51 ===
அரணம் பொருள் என்று, அருள் ஒன்று இலாத அசுரர் தங்கள்
முரண் அன்று அழிய முனிந்தபெம் மானும் முகுந்தனுமே,
' சரணம் சரணம் 'என நின்ற நாயகி தன் ’ அடியார்,
மரணம் பிறவி இரண்டும் எய்தார் , இந்த வையகத்தே.
=== பாடல் 52 ===
வையம், துரகம், மதகரி, மாமகுடம், சிவிகை,
பெய்யும் கனகம்  பெருவிலை ஆரம், பிறைமுடித்த
ஐயன் திருமனை யாள் அடித்தாமரைக்கு அன்புமுன்பு
செய்யும் தவமுடையார்க்கு உளவாகிய சின்னங்களே.
=== பாடல் 53 ===
சின்னஞ்சிறிய மருங்கினில் சாத்திய செய்யபட்டும் ,
பென்னம் பெரிய முலையும், முத்தாரமும், பிச்சிமொய்த்த
கன்னங்கரிய குழலும், கண் மூன்றும், கருத்தில் வைத்துத்
தன்னந்தனி இருப்பார்க்கு இதுபோலும் தவம் இல்லையே.
=== பாடல் 54 ===
இல்லாமை சொல்லி ஒருவர்தம் பாற் சென்று, இழிவுபட்டு
நில்லாமை நெஞ்சில் நினைகுவிரேல், நித்தம் நீடுதவம்
கல்லாமை கற்ற கயவர் தம்பால், ஒரு காலத்திலும்
செல்லாமை வைத்த திரிபுரை பாதங்கள் சேர்மின்களே.
=== பாடல் 55 ===
மின் ஆயிரம் ஒரு மெய்வடி வாகி விளங்குகின்றது
அன்னாள், அகமகிழ் ஆனந்த வல்லி, அருமறைக்கு
முன்னாய், நடு எங்குமாய், முடிவாய முதல்வி தன்னை
உன்னாது ஒழியினும், உன்னினும் வேண்டுவது ஒன்றில்லை
=== பாடல் 56 ===
ஒன்றாய் அரும்பிப் பலவாய் விரிந்து, இவ் வுலகு எங்குமாய்
நின்றாள், அனைத்தையும் நீங்கி நிற்பான் என்தன் நெஞ்சினுள்ளே
பொன்றாது நின்று புரிகின்ற வா இப்பொருள் அறிவார்
அன்று ஆலிலையில் துயின்ற பெம்மானும் என் ஐயனுமே.
=== பாடல் 57 ===
ஐயன் அளந்தபடி இருநாழிகொண்டு அண்டமெல்லாம்
உய்ய அறம் செயும் உன்னையும்போற்றி, ஒருவர் தம்பால்
செய்ய பசுந்தமிழ்ப் பாமாலையும் கொண்டு சென்று பொய்யும்
மெய்யும் இயம்ப வைத்தாய், இதுவோ உன் தன் மெய்யருளே
=== பாடல் 58 ===
அருணாம் புயத்தும், என் சித்தாம் புயத்தும் அமர்ந்திருக்கும்
தருணம் புயமலைத் தையல்நல்லாள் , தகைசேர்நயனக்
கருணாம் புயமும் வதனாம் புயமும், கராம் புயமும்
சரணாம் புயமும் அல்லால் கண்டிலேன் ,ஒரு தஞ்சமுமே
=== பாடல் 59 ===
தஞ்சம் பிறிது இல்லை ஈது அல்லது என்று, உன்தவநெறிக்கே
நெஞ்சம் பயில நினைக்கின்றிலேன்; ஒற்றை நீள் சிலையும்
அஞ்சு அம்பும் இக்கு அலராக நின்றாய்; அறியார் எனினும்
பஞ்சு அஞ்சும் மெல்லடியார் அடியார் பெற்ற பாலரையே
=== பாடல் 60 ===
பாலினும் சொல் இனியாய் பனிமா மலர்ப் பாதம் வைக்க
மாலினும், தேவர் வணங்க நின்றோன் கொன்றைவார் சடையின்
மேலினும், கீழ்நின்று வேதங்கள் பாடும் மெய்ப்பீடம் ஒரு
நாலினும் சாலநன்றோ அடி யேன்முடை நாய்த்தலையே ?
=== பாடல் 61 ===
நாயேனையும் இங்கு ஒருபொருளாக நயந்து வந்து ,
நீயே நினைவின்றி ஆண்டு கொண்டாய் நின்னை உள்ளவண்ணம்
பேயேன் அறியும் அறிவு தந்தாய் ;என்ன பேறு பெற்றேன்
தாயே மலைமகளே செங்கண் மால்திரு  தங்கச்சியே
=== பாடல் 62 ===
தங்கச் சிலைகொண்டு, தானவர் முப்புரம் சாய்த்து மத
வெங்கட் கரி உரி போர்த்த செஞ்சேவகன், மெய் அடையக்
கொங்கைக் குரும்பைக் குறியிட்ட நாயகி, கோகணகச்
செங்கைக் கரும்பும் மலரும் எப்போதும் என் சிந்தையதே
=== பாடல் 63 ===
தேரும் படிசில ஏதுவும் காட்டி, முன் செல்கதிக்குக்
கூறும் பொருள், குன்றிற் கொட்டும் தறிகுறிக்கும் சமயம்
ஆறும் தலைவி இவளாய் இருப்பது அறிந்திருந்தும்
வேறும் சமயம் உண்டு என்று கொண்டாடிய வீணருக்கே.
=== பாடல் 64 ===
வீணே பலி கவர் தெய்வங்கள் பாற்சென்று, மிக்க அன்பு
பூணேன் உனக்கு அன்பு பூண்டு கொண்டேன் நின் புகழ்ச்சியன்றிப்
பேணேன் ; ஒரு பொழுதும் ;  திருமேனிப்ரகாசமன்றிக்
காணேன், இரு நிலமும் திசை நான்கும் ககனமுமே
=== பாடல் 65 ===
ககனமும் வானும் புவனமும் காண விற்காமன் அங்கம்
தகனம்முன் செய்த தவப்பெரு மாற்குத் தடக்கையும் செம்
முகனும்முந் நான்கிரு    மூன்றுஎனத்தோன்றிய மூதறிவின்
மகனும் உன்டாய்தன்றோ? வல்லி நீ செய்த வல்லபமே.
=== பாடல் 66 ===
வல்லபம் ஒன்றறியேன்; சிறியேன் ; நின் மலரடி செம்
பல்லவம் அல்லது பற்று ஒன்று இலேன்; பசும் பொற்பொருப்பு
வில்லவர் தம்முடன் வீற்றிருப்பாய் வினை யேன்தொடுத்த
சொல் அவ மாயினும், நின் திரு நாமங்கள் தோத்திரமே .
=== பாடல் 67 ===
தோத்திரம் செய்து பொழுது, மின் போலும் நின் தோற்றம் ஒரு
மாத்திரைப் போதும் மனத்தில் வையாதவர் வன்மை குலம்
கோத்திரம் கல்வி, குணம் குன்றி ,நாளும் குடில்கள் தோறும்
பாத்திரம் கொண்டு பலிக்குஉழலா நிற்பர் பார் எங்குமே.
=== பாடல் 68 ===
பாரும், புனலும், கனலும் வெங் காலும் படர் விசும்பும் ;
ஊரும் முருகு சுவைஒளி ஊறொலி ஒன்றுபடச்
சேரும் தலைவி !  சிவகாம சுந்தரி ! சீறடிக்கே
சாரும் தவம் உடையார் படையாத தனம் இல்லையே .
=== பாடல் 69 ===
தனம்தரும் ; கல்விதரும் ; ஒருநாளும் தளர்வறியா
மனம்தரும் ; தெய்வ வடிவம் தரும் நெஞ்சில் வஞ்சமில்லா
இனம்தரும் ; நல்லன எல்லாம் தரும் அன்பர் என்பவர்க்கே
கனம் தரும் ; பூங்குழலாள் அபிராமி கடைக்கண்களே.
=== பாடல் 70 ===
கண்களிக் கும்படி கண்டு கொண்டேன் கடம்பாடவியில்
பண்களிக் கும்குரல் வீணையும் கையும் பயோதரமும்
மண்களிக் கும்பச்சை வண்ணமும் ஆகி மதங்கர் குலப்
பெண்களில் தோன்றிய எம்பெரு மாட்டி தன் பேரழகே.
=== பாடல் 71 ===
அழகுக் கொருவரும் ஒவ்வாத வல்லி, அருமறைகள்
பழகிச் சிவந்த பாதாம் புயத்தாள் பனிமாமதியின்
குழவித் திருமுடிக் கோமள யாமளைக் கொம்பிருக்க
இழவுற்று நின்நெஞ்சே ; இரங்கேல் உனக்கென் குறையே
=== பாடல் 72 ===
என்குறை தீரநின்  றேத்துகிறேன்; இனி யான்பிறக்கின் ;
நின்குறையே அன்றி யார்குறை காண்இரு நீள்விசும்பின்
மின்குறை காட்டி மெலிகின்ற நேரிடை மெல்லியலாய்
தன்குறை தீர ,எம்கோன்சடை  மேல்வைத்த தாமரையே.
=== பாடல் 73 ===
தாமம் கடம்பு ; படைபஞ்ச பாணம்; தனுக் கரும்பு ;
யாமம் வயிரவர் ஏத்தும் பொழுதெமக்கென்று வைத்த
சேமம் திருவடி; செங்கைகள் நான்கொளி செம்மை அம்மை
நாமம் திரிபுரை ஒன்றோடிரண்டு நயனங்களே
=== பாடல் 74 ===
நயனங்கள் மூன்றுடை நாதனும் வேதமும், நாரணனும்
அயனும் பரவும் அபிராம வல்லி அடியிணையைப்
பயனென்று கொண்டவர் பாவையர் ஆடவும் பாடவும் பொன்
சயனம் பொருந்து தமனியக் காவினில் தங்குவரே
=== பாடல் 75 ===
தங்குவர் கற்பகத் தாருவின் நீழலில்; தாயர் இன்றி
மங்குவர் மண்ணில் வழுவாய் பிறவியை மால்வரையும்
பொங்குவர் ஆழியும் ஈரேழு புவனமும், பூத்தஉந்திக்
கொங்கிவர் பூங்குழலாள் திருமேனி குறித்தவரே.
=== பாடல் 76 ===
குறித்தேன் மனத்தினில், நின் கோலம் எல்லாம்; நின் குறிப் பறிந்து
மறித்தேன் மறலி வருகின்ற நேர்வழி; வண்டு கிண்டி
வெறித்தேன் அவிழ்கொன்றை வேணி பிரான் ஒரு கூற்றை, மெய்யில்
பறித்தே குடி புகுதும் பஞ்ச பாணபயிரவியே !
=== பாடல் 77 ===
பயிரவி ! பஞ்சமி ! பாசாங் குசை பஞ்சபாணி ! வஞ்சர்
உயிர் அவி உண்ணும் உயர்சண்டி !காளி ! ஒளிரும்கலா
வயிரவி ! மண்டலி !மாலினி  !சூலி !வராகி- என்றே
செயிர் அவி நான்மறை சேர் திருநாமங்கள் செப்புவரே.
=== பாடல் 78 ===
செப்புக் கனக  கலசமும் போலும் திருமுலை மேல்
அப்பும் களப அபிராமவல்லி ! அணிதரளக்
கொப்பும் வயிரக் குழையும், விழியின் கொழுக்கட்டையும்,
துப்பும் நிலவும் எழுதிவைத்தேன் என் துணைவிழிக்கே.
=== பாடல் 79 ===
விழிக்கே அருளுண்டு அபிராம வல்லிக்கு வேதம் சொன்ன
வழிக்கே வழிபட நெஞ்சுண்டு எமக்கு; அவ்வழி கிடக்கப்
பழிக்கே சுழன்றுவெம் பாவங்களே செய்து, பாழ்நரகக்
குழிக்கே அழுந்தும் கயவர் தம் மோடென்ன கூட்டினியே ?
=== பாடல் 80 ===
கூட்டியவா என்னை தன் அடியாரில் !கொடிய வினை
ஓட்டியவா என்கண் ஓடியவா தன்னை உள்ளவண்ணம்
காட்டியவா ! கண்ட கண்ணும் மனமும் களிக்கின்றவா !
ஆட்டியவா நடம் ! ஆடகத் தாமரை ஆரணங்கே.
=== பாடல் 81 ===
அணங்கே ! அணங்குகள் நின் பரி வாரங்கள் ஆகையினால்
வணங்கேன் ஒருவரை வாழ்த்துகிலேன் நெஞ்சில் வஞ்சகரோடு
இணங்கேன் ;  எனதுன தென்றிருப் பார்சிலர் யாவரோடும்
பிணங்கேன் அறிவொன்றிலேன் என்கண் நீ வைத்த பேரளியே .
=== பாடல் 82 ===
அளியார் கமலத்தில் ஆரணங்கே !  அகிலாண்டமும் நின்
ஒளியாக நின்ற ஒளிர் திரு மேனியை உள்ளுதொறும்
களியாகி அந்தகரணங்கள் விம்மிக் கரைபுரண்டு
வெளியாய் விடின் எங்ஙனே மறப்பேன் நின் விரகினையே.
=== பாடல் 83 ===
விரவும் புதுமலர் இட்டு,நின் பாத விரைக்கமலம்
இரவும் பகலும் இறைஞ்ச வல்லார் இமையோர் எவரும்
பரவும், பதமும், அயிராவதமும், பகீரதியும்
உரவும் குலிசமும் கற்பகக் காவும் உடையவரே.
=== பாடல் 84 ===
உடையாளை ஒல்குசெம்பட்டுடையானை ஒளிர்மதிச்செஞ்
சடையாளை வஞ்சகர் நெஞ்சடையாளைத் தயங்கும் நுண்ணூல்
இடையாளை ,எங்கள் பெம்மானிடையாளை இங்கென்னை இனிப்
படையாளை உங்களையும் படையாவண்ணம் பார்த்திருமே
=== பாடல் 85 ===
பார்க்கும் திசைதொறும் பாசாங்குசமும் பனிச் சிறைவண்டு
ஆர்க்கும் புதுமலர் ஐந்தும், கரும்பும், என் அல்லல் எல்லாம்
தீர்க்கும் திரிபுரையாள் திரு மேனியும் சிற்றிடையும்,
வார்க்கும் குங்கும முலையும் ,முலைமேல் முத்து மாலையுமே.
=== பாடல் 86 ===
மால் அயன் தேட மறை தேட வானவர்தேட நின்ற
காலையும், சூடகக் கையையும் கொண்டு, கதித்தகப்பு
வேலைவெங்காலன் என்மேல் விடும்போது வெளிநில்கண்டாய்
பாலையும் தேனையும் பாகையும் போலும் பணிமொழியே!
=== பாடல் 87 ===
மொழிக்கும், நினைவுக்கும் எட்டாத நின் திருமூர்த்தி, எந்தன்
விழிக்கும் வினைக்கும் வெளி நின்றதால் ;விழியால் மதனை
அழிக்கும் தலைவர் அழியா விரதத்தை , அண்டமெல்லாம்
பழிக்கும் படி, ஒரு பாகம் கொண்டாளும் பராபரையே !
=== பாடல் 88 ===
பரம் என்றுனை அடைந்தேன் தமியேனும் உன் பத்தருக்குள்
தரம் அன்று இவன் என்று தள்ளத் தகாது தரியலர்தம்
புரம் அன்று எரியப் பொருப்புவில் வாங்கிய , போதில் அயன்
சிரம் ஒன்று செற்றகை யான் இடப் பாகம் சிறந்தவளே !
=== பாடல் 89 ===
சிறக்கும் கமலத்திருவே நின் சேவடி சென்னிவைக்கத்
துறக்கம் தரும்நின் துணைவரும் நீயும், துரியமற்ற
உறக்கம் தரவந்து , உடம்போடு உயிர் உறவு அற்று அறிவு
மறக்கும் பொழுதென்முன்னே வரல் வேண்டும் வருந்தியுமே.
=== பாடல் 90 ===
வருந்தாவகை என் மனத்தா மரையினில் வந்து புகுந்து
இருந்தாள், பழைய இருப்பிடமாக ; இனி எனக்குப்
பொருந்தாது ஒரு பொருள் இல்லைவிண் மேவும் புலவருக்கு
விருந்தாக, வேலை மருந்தானதை நல்கும் மெல்லியலே .
=== பாடல் 91 ===
மெல்லிய நுண்ணிடை மின்னனையாளை விரிசடையோன்
புல்லிய மென்முலை பொன்னனை யாளைப் புகழ்ந்துமறை
சொல்லிய வண்ணம்தொழும் அடியாரைத்தொழும் அவர்க்கு
பல்லியம் ஆர்த்து எழ வெண்பக டூரும் பதம் தருமே .
=== பாடல் 92 ===
பதத்தே உருகி நின் பாதத்திலே மனம் பற்றி, உன்றன்
இதத்தே ஒழுக, அடிமை கொண்டாய்; இனி யான் ஒருவர்
மதத்தே மதிமயங்கேன்; அவர் போன வழியும் செல்லேன் !
முதல்தேவர் மூவரும் யாவரும் போற்றும் முகிழ்நகையே !
=== பாடல் 93 ===
நகையை இஃதிந்த ஞாலம் எல்லாம் பெற்ற நாயகிக்கு
முகையே, முகிழ்முலை மானே முதுகண் முடிவில் அந்த
வகையே பிறவியும் வம்பே ;மலைமகள் என்பது நாம் ;
மிகையே, இவள்தன் தகைமையை நாடி விரும்புவதே
=== பாடல் 94 ===
விரும்பித் தொழும் அடியார் விழி நீர் மல்கி, மெய்ப்புளகம்
அரும்பித் ததும்பிய ஆனந்த மாகி, அறிவிழந்து,
சுரும்பிற் களித்து ,மொழிதடு மாறி முன் சொன்ன எல்லாம்
தரும் பித்தர் ஆவரென்றால் , அபிராமி சமயம் நன்றே.
=== பாடல் 95 ===
நன்றே வருகினும், தீதே விளைகினும், நான் அறிவது
ஒன்றேயும் இல்லை, உன்னைகே பரம் எனக் குள்ளவெல்லாம்
அன்றே உனதென் றளித்துவிட்டேன்; அழியாதகுணக்
குன்றே! அருட்கடலே! இம வான்பெற்ற கோமளமே !
=== பாடல் 96 ===
கோமளவல்லியை, அல்லியந் தாமரைக் கோயில்வைகும்
யாமள வல்லியை , ஏதமி லாளை , எழுதரிய
சாமள மேனிச் சகல கலாமயில் தன்னைத் தம்மால்
ஆமள வும் தொழுவார், எழு பாருக்கும் ஆதிபரே.
=== பாடல் 97 ===
ஆதித்தன் ,அம்புலி அங்கி, குபேரன் அமரர்தங்கோன்,
போதில் பிரமன் ,புராரி , முராரி பொதியமுனி
காதிப் பொருபடைக் கந்தன், கணபதி ,காமன் முதல்
சாதித்த புண்ணியர் எண்ணிலர் - போற்றுவர் தையலையே
=== பாடல் 98 ===
தை வந்து நின் அடித்தாமரை சூடிய சங்கரற்குக்
கைவந்த தீயும் தலை வந்த ஆறும் கரந்தது எங்கே
மெய்வந்த நெஞ்சின் அல்லால் ,ஒருகாலும் விரகர் தங்கள்
பொய்வந்த நெஞ்சில் புகல் அறியாமடப் பூங்குயிலே !
=== பாடல் 99 ===
குயிலே இருக்கும் கடம்பாட வியிடை; கோல இயல்
மயிலாய் இருக்கும் இமயாசலத்திடை ; வந்து உதித்த
வெயிலாய் இருக்கும் விசும்பில்; கமலத்தின்மீது அன்னமாம்
கயிலாயருக்கு அன்று இமவான் அளித்த கனங்குழையே
=== பாடல் 100 ===
குழையைத்தழுவிய கொன்றையந் தார்கமழ் கொங்கைவல்லி
கழையைப் பொருத திருநெடுந் தோளும் , கருப்புவில்லும்
விழையைப் பொருதிறல் வேரியம் பாணமும் ,வெண்ணகையும்
உறையைப் பொரு கண்ணும், நெஞ்சில் எப்போதும்  உதிக்கின்றனவே.
=== நூல் பயன் ===
ஆத்தாளை எங்கள் அபிராமவல்லியை அண்டமெல்லாம்
பூத்தாளை மாதுளம் பூ நிறத்தாளை புவி அடங்கக்
காத்தாளை அங்கயர்கண்ணியை
கரும்பு வில்லும் பாசாங்குசமும் சேர்த்தாளை முக்கண்ணியைத் தொழுவார்க்கு ஒரு தீங்கல்லையே`,
      english: `|| Sri Abirami Anthadhi (Complete 100 Verses) ||

(Synchronized LRC Chanting available in Tamil & LRC tab)

|| ஸ்ரீ அபிராமி அந்தாதி ||
அருளியவர்: ஸ்ரீ அபிராமி பட்டர்
=== காப்பு ===
தாரமர் கொன்றையும் செண்பக மாலையுஞ் சாத்தும்தில்லை
ஊரர் தம் பாகத்து உமை மைந்தனே !  உலகேழும் பெற்ற
சீர் அபிராமி அந்தாதி எப்போதும் என் சிந்தையுள்ளே
காரமர் மேனிக் கணபதியே ! நிற்கக் கட்டுரையே
=== பாடல் 1 ===
உதிக்கின்ற செங்கதிர் உச்சித் திலகம், உணர்வுடையோர்
மதிக்கின்ற மாணிக்கம், மாதுளம்போது மலர்க்கமலை
துதிக்கின்ற மின்கொடி, மென்கடிக் குங்கும தோயம் என்ன
விதிக்கின்ற மேனி அபிராமி என்தன் விழுத்துணையே
=== பாடல் 2 ===
துணையும், தொழுந் தெய்வமும், பெற்ற தாயும், சுருதிகளின்
பணையும், கொழுந்தும், பதிகொண்ட வேரும், பனி மலர்பூங்`,
      meaning: `திருவருள் நிறைந்த திருக்கடையூர் அன்னை அபிராமி மீது அபிராமி பட்டர் பாடிய 100 பாடல்கள். அந்தாதியாக அமைந்த இப்பாடல்களை பாராயணம் செய்வோருக்கு எமபயம் அண்டாது, சகல செல்வங்களும் நிறையும்.`
    }
